const LINEAR_GRAPHQL_URL = 'https://api.linear.app/graphql';
const SLACK_POST_MESSAGE_URL = 'https://slack.com/api/chat.postMessage';

const REACTION_MUTATION = `
mutation AddReaction($input: ReactionCreateInput!) {
  reactionCreate(input: $input) {
    success
    reaction {
      id
      type
      user {
        id
        name
      }
    }
  }
}
`;

async function graphqlRequest(
  fetchImpl: typeof fetch,
  apiKey: string,
  variables: Record<string, unknown>
): Promise<unknown> {
  const response = await fetchImpl(LINEAR_GRAPHQL_URL, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      query: REACTION_MUTATION,
      variables,
    }),
  });

  if (!response.ok) {
    throw new Error(`Linear GraphQL request failed: ${response.status} ${response.statusText} at ${LINEAR_GRAPHQL_URL}`);
  }

  return response.json();
}

async function slackPostMessage(
  fetchImpl: typeof fetch,
  botToken: string,
  channel: string,
  threadTs: string,
  text: string
): Promise<unknown> {
  const response = await fetchImpl(SLACK_POST_MESSAGE_URL, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${botToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      channel,
      thread_ts: threadTs,
      text,
    }),
  });

  if (!response.ok) {
    throw new Error(`Slack postMessage failed: ${response.status} ${response.statusText} at ${SLACK_POST_MESSAGE_URL}`);
  }

  return response.json();
}

export async function handle(
  payload: LinearWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!payload.action) throw new Error('Missing required field: action');
  if (!payload.type) throw new Error('Missing required field: type');
  if (!payload.data) throw new Error('Missing required field: data');
  if (!payload.data.id) throw new Error('Missing required field: data.id');
  if (!payload.data.body) throw new Error('Missing required field: data.body');
  if (!payload.actor) throw new Error('Missing required field: actor');
  if (!payload.actor.id) throw new Error('Missing required field: actor.id');

  if (payload.action !== 'create') {
    throw new Error(`Unsupported action: ${payload.action}, expected 'create'`);
  }
  if (payload.type !== 'Comment') {
    throw new Error(`Unsupported type: ${payload.type}, expected 'Comment'`);
  }

  const commentId = payload.data.id;
  const commentBody = payload.data.body;
  const actorId = payload.actor.id;
  const reactableId = payload.data.reactableId ?? commentId;
  const reactionType = config.reactionType ?? 'THUMBS_UP';

  const fetchImpl = config.fetch ?? globalThis.fetch;

  const linearResponse = await graphqlRequest(fetchImpl, config.linearApiKey, {
    input: {
      reactableId,
      userId: actorId,
      type: reactionType,
    },
  });

  const linearData = linearResponse as {
    data?: {
      reactionCreate?: {
        success?: boolean;
        reaction?: {
          id?: string;
        };
      };
    };
  };

  if (!linearData.data?.reactionCreate?.success || !linearData.data.reactionCreate.reaction?.id) {
    throw new Error('Linear GraphQL mutation did not return a successful reaction creation');
  }

  const linearReactionId = linearData.data.reactionCreate.reaction.id;

  const slackResponse = await slackPostMessage(
    fetchImpl,
    config.slackBotToken,
    config.slackChannel,
    config.slackThreadTs,
    commentBody
  );

  const slackData = slackResponse as {
    ok?: boolean;
    ts?: string;
  };

  if (!slackData.ok || !slackData.ts) {
    throw new Error('Slack postMessage did not return a successful response with timestamp');
  }

  const slackMessageTs = slackData.ts;

  return {
    linearReactionId,
    slackMessageTs,
  };
}

